# Validate inputs
for arr in [logp_with_result, logp_call_only, logp_no_call]:
    if not isinstance(arr, np.ndarray):
        raise ValueError("Each input must be a numpy array")
    if arr.ndim != 2:
        raise ValueError("Each input must be a 2D matrix")
    if arr.size == 0:
        raise ValueError("Input array must not be empty")
    if not np.all(np.isfinite(arr)):
        raise ValueError("All input values must be finite")
    if np.any(arr > 0):
        raise ValueError("All input values must be nonpositive")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("All input arrays must have the same shape")
if isinstance(tau_filter, bool) or not isinstance(tau_filter, (int, float)):
    raise ValueError("tau_filter must be a non-boolean numeric value")
if not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("tau_filter must be finite and nonnegative")
total_with = np.sum(logp_with_result, axis=1)
total_call_only = np.sum(logp_call_only, axis=1)
total_no_call = np.sum(logp_no_call, axis=1)
best_alt = np.maximum(total_no_call, total_call_only)
margins = total_with - best_alt
keep = margins > tau_filter
return keep, margins
